"""Complete Chilean platters, turkey mayonnaise and Burnet variations."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']
END='Keep covered at 4°C (40°F) or colder until serving. Refrigerate leftovers within 2 hours and use within 2 days. Do not leave the platter at room temperature for more than 2 hours.'
REF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'
def finish(r):r['category']='Main dishes';r['source']+=REF;return eggsource(r)

PLATTER=[I('shellfish',600,'g','commercially canned cooked mussel meat, drained weight','Use the same drained weight of commercially canned cooked clams, or the complete roast-chicken variation.'),I('lettuce',200,'g','lettuce leaves and hearts, washed and dried','Use the same weight of butterhead lettuce.'),I('radishes',120,'g','radishes, trimmed and washed','Use the same weight of thinly sliced mild turnip.'),I('celery',100,'g','tender celery stalks, washed','Use the same weight of fennel stalks for a different flavor.'),water(500,'crispwater')]
PLATE=['Drain {{shellfish}} well and refrigerate. Cut {{radishes}} into thin rounds. Split the ends of {{celery}} into fine strips, leaving their bases attached, and stand in cold {{crispwater}} for 15 minutes to curl slightly; drain and pat dry.','Arrange {{lettuce}} on a platter, keeping the small heart leaves for the top. Place the cold shellfish in the center. Spoon the mayonnaise over it, then arrange the lettuce hearts, radish rounds and celery around and over the platter.',END]
def chickenvariation(r):
 items=[copy.deepcopy(i) for i in r['ingredients'] if i['key']!='shellfish']+[I('chicken',900,'g','raw boneless skinless chicken thighs','Use the same weight of boneless skinless chicken breast; check earlier for doneness.'),I('roastoil',15,'ml','olive oil for roasting','Use the same volume of sunflower oil.'),I('roastsalt',.5,'tsp','fine salt for roasting','Reduce or omit.')]
 steps=['Heat the oven to 190°C (375°F). Put {{chicken}} in a snug roasting dish and coat with {{roastoil}} and {{roastsalt}}. Roast for about 30–40 minutes, until the thickest part reaches 74°C (165°F).','Rest for 10 minutes, slice, spread in a shallow container and refrigerate promptly, within 2 hours of cooking, for about 1 hour until cold. Prepare the sauce and vegetables during chilling.']+copy.deepcopy(r['steps'])
 steps=[s.replace('Drain {{shellfish}} well and refrigerate. ','').replace('cold shellfish','cold roast chicken') for s in steps]
 variant(r,'roast-chicken','Roast chicken platter',items,steps)
 r['notes']+=' The full poultry variation uses a modern boneless roast for easy portioning; allow about 2 hours total, including cooling.'

r=add(13,'Chilean Shellfish Platter with Eight-Yolk Mayonnaise',8,35,'Cold mussels sit on lettuce under a rich vinegar mayonnaise, with crisp radishes and curled celery.',[yolks(8),oil(375),vinegar(45),salt(1)]+copy.deepcopy(PLATTER),['Whisk {{yolks}} in a large clean bowl. Gradually whisk in {{oil}}, starting with drops and continuing in a thin stream as the mixture emulsifies. Stop pouring if oil collects on the surface and whisk until it blends in.','Gradually whisk in {{vinegar}} and {{salt}}. The mayonnaise is ready when smooth and creamy; no cooking or three-hour beating is needed. Refrigerate while preparing the platter.']+PLATE,'The full source platter and its shellfish-or-roast-poultry alternative are retained. Eight pasteurized yolks are chosen from the original eight-to-ten range. The source half regular bottle is supplied as a modern 375 ml working amount, not a verified historical bottle conversion. Repeated two-tablespoon additions describe the mixing technique, not additional oil. The original three-hour beating is replaced by emulsifying until smooth; beating does not cook eggs. Commercially canned cooked mussels supply the unspecified preserved shellfish.');finish(r);chickenvariation(r)

r=add(14,'Chilean Shellfish Platter with Cooked-Yolk Mayonnaise',8,45,'A thick mayonnaise of sieved cooked yolks and pasteurized yolks coats a cold mussel platter garnished with lettuce, radish and celery.',[eggs(7),water(2000),yolks(2),oil(375),vinegar(45),salt(1)]+copy.deepcopy(PLATTER),boil()+['Separate the firm cooked yolks and push through a fine sieve into a clean bowl. Refrigerate the cooked whites for another dish. Beat {{yolks}} into the sieved yolks until smooth.','Gradually whisk in {{oil}}, a few drops at first, then in a thin stream. Slowly add {{vinegar}} and {{salt}}. If the sauce separates, put a teaspoon of cold drinking water in a clean bowl and gradually whisk the broken sauce into it; this small repair addition changes the yield slightly. Refrigerate while preparing the platter.']+PLATE,'The seven cooked yolks and two uncooked yolks distinguish this formula from the previous eight-yolk platter; they are not duplicates. Pasteurized yolks replace the uncooked yolks. The source half bottle is a supplied modern 375 ml, not a verified historical conversion. The instruction to arrange as the preceding recipe is expanded to the full shellfish platter and roast-poultry variation.');finish(r);chickenvariation(r)

r=add(22,'Guaxolotillo en Mayonesa — Cold Turkey with Herb Sauce and Aspic',8,360,'Roasted turkey is chilled and dressed with herb ravigote and mayonnaise, then garnished with capers, anchovies, cucumber and savory jelly.',[
 I('turkey',2500,'g','small whole oven-ready turkey, fully thawed, giblets removed','Use a similar-sized whole turkey; a larger bird needs more cooking and cooling time.'),I('roastoil',20,'ml','olive oil for roasting','Use the same volume of sunflower oil.'),I('roastsalt',8,'g','fine salt for the turkey','Reduce or omit.'),water(250,'panwater'),
 I('aspicstock',250,'ml','unsalted prepared turkey stock for the jelly','Use the same volume of unsalted prepared chicken stock.'),I('gelatin',6,'g','unflavored powdered gelatin','Use equivalent-strength leaf gelatin according to its package.'),water(30,'bloomwater'),
 I('butter',12,'g','unsalted butter for the white sauce','Use the same weight of a block-style dairy-free butter alternative.'),I('flour',8,'g','plain flour','Use the same weight of a plain gluten-free flour blend suitable for sauces.'),I('mushroom',25,'g','white mushrooms, cleaned and finely chopped','Use the same weight of cremini mushrooms; the sauce will be darker.'),I('saucestock',120,'ml','unsalted prepared chicken stock for the white sauce','Use the same volume of unsalted prepared turkey stock.'),I('chervil',2,'g','fresh chervil, finely chopped','Use the same weight of parsley; the flavor differs.'),I('burnet',2,'g','fresh salad burnet leaves, finely chopped','Use the same weight of parsley if unavailable; the cucumber-like flavor is lost.'),I('chives',2,'g','fresh chives, finely chopped','Use the same weight of tender spring onion greens.'),I('tarragon',3,'g','fresh tarragon leaves, finely chopped','Use 1 g dried tarragon for a different intensity.'),I('herbvinegar',10,'ml','white wine vinegar for the herb sauce','Use the same volume of cider vinegar.'),I('herboil',10,'ml','olive oil for the cold herb sauce','Use the same volume of sunflower oil.'),I('allspice',.0625,'tsp','ground allspice','Omit if unavailable; do not replace with mixed spice.'),I('herbsalt',.125,'tsp','fine salt for the herb sauce','Reduce or omit.'),
 I('dressoil',15,'ml','olive oil for dressing the turkey','Use the same volume of sunflower oil.'),I('dressvinegar',15,'ml','white wine vinegar for dressing the turkey','Use the same volume of cider vinegar.'),eggs(1),water(750),yolks(2),oil(180),vinegar(15),salt(.5),I('capers',20,'g','capers, drained','Use the same weight of finely chopped cornichons.'),I('anchovies',25,'g','oil-packed anchovy fillets, drained','Use the same weight of extra capers for a fish-free garnish; flavor differs.'),I('cucumber',150,'g','cucumber, washed and thinly sliced','Use the same weight of mild pickled cucumber, drained.')],
 ['Heat the oven to 170°C (340°F). Pat {{turkey}} dry without rinsing. Rub with {{roastoil}} and {{roastsalt}}. Set breast-side up on a rack in a roasting tin and pour {{panwater}} into the tin. Leave the cavity empty.','Roast for about 2–3 hours, checking from 1½ hours because small birds vary. Cover the breast loosely with foil if browning too quickly. The thickest breast, innermost thigh and wing must all reach 74°C (165°F), with the thermometer clear of bone. Add a little hot water to the tin if it dries out.','Rest for 20 minutes, then carve and remove the bones. Spread the meat in shallow containers and refrigerate promptly, within 2 hours of cooking, until cold, about 1–2 hours. Keep the roasting liquid for another use; it is not required for the measured sauces below.','While the turkey roasts, sprinkle {{gelatin}} over cold {{bloomwater}} and leave for 5 minutes. Heat {{aspicstock}} until steaming, remove from heat and stir in the bloomed gelatin until dissolved. Pour into a shallow container, cover and refrigerate for at least 3 hours until firm. Cut into small cubes.','For the ravigote base, melt {{butter}} in a small saucepan. Cook {{mushroom}} for 3 minutes without browning. Stir in {{flour}} and cook for 1 minute. Gradually whisk in {{saucestock}} and simmer for 8 minutes, stirring, until smooth and lightly thickened. Press through a fine sieve and discard the mushroom pieces. Transfer the sauce to a shallow bowl and refrigerate promptly for about 30 minutes until cold.','Whisk {{herbvinegar}}, {{herboil}}, {{herbsalt}} and {{allspice}} into the cold white sauce. Stir in {{chervil}}, {{burnet}}, {{chives}} and {{tarragon}}. Keep refrigerated.']+boil()+['Separate the cooked yolk, sieve it into a clean bowl and reserve the white for another dish. Beat in {{yolks}}, then gradually whisk in {{oil}}, starting with drops and progressing to a thin stream. Slowly whisk in {{vinegar}} and {{salt}} until smooth. Refrigerate.','Toss the cold turkey pieces with {{dressoil}}, {{dressvinegar}} and the cold herb sauce. Arrange on a platter and cover with the mayonnaise. Garnish with {{capers}}, {{anchovies}} and {{cucumber}}, and arrange the aspic cubes as a border. Serve cold.',END],
 'The brief turkey entry refers to rabbit or pheasant; the complete rabbit method supplies the oil, vinegar, ravigote, mayonnaise, capers, anchovies, cucumber and meat-jelly border. All components are expanded here. The book’s cold oil-ravigote variation is used: a chilled velouté with chervil, salad burnet, chives, more tarragon and equal vinegar and oil. Sustancia blanca means white butter-and-flour roux, not white stock. Prepared stock and a small mushroom roux provide an explicit modern shortcut to the longer stock-making reference. Turkey size and every unspecified component amount are modern working quantities. Total time includes concurrent jelly setting and chilling.');finish(r)

r=add(24,'Mayonesa a la Burnet — Lemon Mayonnaise',16,20,'A lemon-forward olive-oil mayonnaise with a small vinegar finish, accompanied by complete green-herb and cooked calf-brain variations.',[yolks(1),oil(250),lemon(30),vinegar(15),salt(.25)],['Whisk {{yolks}}, {{lemon}} and {{salt}} in a clean bowl. Gradually whisk in {{oil}}, drop by drop at first, then in a thin stream. As the sauce thickens, gradually whisk in {{vinegar}}. Stop pouring oil whenever it pools, and whisk until it blends in before continuing.','If the mixture separates, put a teaspoon of cold drinking water in a clean bowl and gradually whisk the separated sauce into it a few drops at a time; this small repair addition changes the yield slightly. The sauce should be smooth and spoonable.','Serve a small spoonful with already-cooked chilled fish or cooked vegetable salads. The serving suggestion does not form part of the measured sauce recipe.',COLD], 'The original says one cuartillo of oil, not a verified quarter liter. The 250 ml oil here is an explicit modern working quantity, not a historical-unit conversion. One lemon is standardized to 30 ml juice. Sixteen small condiment servings are estimated. Burnet is the source attribution in the title, not an instruction to add salad burnet. The spinach-green reference is expanded in a named variation. The original snow wording is interpreted as external cooling; a bowl over clean ice water may be used without adding snow to the food. The calf-brain alternative is retained as a fully cooked modern variation, never raw.');eggsource(r)
vi=copy.deepcopy(r['ingredients'])+[I('spinach',40,'g','fresh spinach leaves, washed','Use the same weight of baby spinach.'),I('greenparsley',5,'g','fresh parsley leaves, washed','Use the same weight of chervil.'),I('oniongreens',5,'g','tender spring onion greens, washed','Use the same weight of chives.'),water(500,'greenwater')]
vs=['Bring {{greenwater}} to a boil. Add {{spinach}}, {{greenparsley}} and {{oniongreens}} and blanch for 30–60 seconds until wilted. Drain, refresh under cold running drinking water, then squeeze very dry in a clean cloth. Mince and pound to a fine paste, then press through a fine sieve; discard coarse fibers.']+copy.deepcopy(r['steps']);vs.insert(3,'Fold the fine green paste into the mayonnaise until evenly colored. Keep refrigerated.');variant(r,'spinach-green','Green spinach-and-herb mayonnaise',vi,vs)
vi=[copy.deepcopy(i) for i in r['ingredients'] if i['key']!='yolks']+[I('brains',150,'g','food-grade calf brains, cleaned and membranes removed by an inspected butcher','Use the pasteurized-yolk base recipe if unavailable; do not use uninspected or wild-animal brain.'),water(500,'poachwater'),I('poachvinegar',15,'ml','white wine vinegar for poaching','Use the same volume of cider vinegar.'),I('poachsalt',2,'g','fine salt for poaching','Reduce or omit.')]
vs=['Bring {{poachwater}}, {{poachvinegar}} and {{poachsalt}} to a gentle simmer in a small saucepan. Add {{brains}} and poach gently for about 15–20 minutes, until the center reaches at least 71°C (160°F). Drain, rest for 3 minutes, then put in a shallow covered container and refrigerate promptly until cold, about 45 minutes.','Press the cooked chilled brains through a fine sieve into a bowl. Beat in {{lemon}} and {{salt}} until smooth. Gradually beat in {{oil}}, beginning drop by drop, then slowly add {{vinegar}}. This makes a soft creamy sauce; its texture differs from the egg-yolk version.','Serve chilled as a small condiment with cooked foods. Keep covered at 4°C (40°F) or colder and use within 2 days. Refrigerate within 2 hours of preparation, or within 1 hour if the room is hotter than 32°C (90°F).'];variant(r,'cooked-calf-brain','Cooked calf-brain variation',vi,vs);r['notes']+=' Allow about 90 minutes for the calf-brain variation, including chilling. Its quantity and cooking method are modern additions to the source substitution; cooking cannot make uninspected meat suitable for use.';r['source']+=REF

assert len(newids)==4,len(newids)
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full original platters and sauce cross-references completed; meaningful variations preserved','repair-batch-024.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=0,totalOverrides=len(records),totalAliases=len(aliases))))

